<!doctype html><html lang="ro"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#172033;font-size:10px}.company{border-bottom:2px solid #1769d1;padding-bottom:12px;margin-bottom:17px}.company-name{font-size:16px;font-weight:bold;color:#123b76}.company-details{color:#526070;line-height:1.55;margin-top:3px}h1{text-align:center;font-size:17px;margin:0 0 5px}.sub{text-align:center;color:#526070;margin-bottom:18px}table{width:100%;border-collapse:collapse}th{background:#e8eef8}th,td{border:1px solid #b9c7d8;padding:6px}.right{text-align:right}.difference{font-weight:bold;color:#a16207}.signatures{margin-top:42px}.signature{display:inline-block;width:30%;margin-right:3%;text-align:center;border-top:1px solid #64748b;padding-top:7px}</style></head><body><header class="company"><div class="company-name">{{ $company->name ?: 'Date firmă necompletate' }}</div><div class="company-details">@if($company->cui)CUI: {{ $company->cui }}@endif @if($company->registration_number) · Reg. Com.: {{ $company->registration_number }}@endif<br>{{ collect([$company->address,$company->city,$company->county,$company->postal_code])->filter()->implode(', ') }}<br>@if($company->email){{ $company->email }}@endif @if($company->phone) · {{ $company->phone }}@endif</div></header><h1>LISTĂ DE INVENTARIERE</h1><p class="sub">{{ $inventoryDocument->number }} · Data: {{ optional($inventoryDocument->inventoried_at)->format('d.m.Y') }} · Gestiune: {{ $inventoryDocument->warehouse?->name }}</p><table><thead><tr><th>Nr.</th><th>Produs</th><th>U.M.</th><th>Stoc scriptic</th><th>Stoc constatat</th><th>Diferență</th><th>Valoare diferență</th></tr></thead><tbody>@foreach($inventoryDocument->items as $index => $item)@php($difference=(float)$item->counted_quantity-(float)$item->book_quantity)<tr><td>{{ $index+1 }}</td><td>{{ $item->product_name }}</td><td>{{ $item->unit }}</td><td class="right">{{ number_format((float)$item->book_quantity,3,',','.') }}</td><td class="right">{{ number_format((float)$item->counted_quantity,3,',','.') }}</td><td class="right {{ $difference != 0 ? 'difference' : '' }}">{{ number_format($difference,3,',','.') }}</td><td class="right">{{ number_format($difference*(float)$item->unit_price,2,',','.') }} RON</td></tr>@endforeach</tbody></table>@if($inventoryDocument->notes)<p><b>Observații:</b> {{ $inventoryDocument->notes }}</p>@endif<p class="signatures"><span class="signature">Comisia de inventariere</span><span class="signature">Gestionar</span><span class="signature">Administrator</span></p></body></html>
